package dev.zomboid.clans;
import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.EditBox;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import me.danialisntcool.factionfriction.client.ui.ModernButton;import me.danialisntcool.factionfriction.client.screen.MainFactionScreen;
/** No remote enemy positions; this notebook displays only server-filtered squad entries. */
public final class ClanScreen extends Screen {
 private int tab,page,ticks,x,y,w,h;private EditBox target,motto;private int badge,doctrine;private boolean siege=true,editing;private int confirm;private String savedTarget="",savedMotto="",profileId="",controls="";
 private static final String[] BADGES={"RADIO","SKULL","MEDIC","TOOLS","STARS"},DOCTRINES={"Supervivientes","Nómadas","Milicia","Rescatistas","Recolectores"};
 public ClanScreen(){super(Component.literal("Cuaderno de supervivencia"));}
 protected void init(){ClientClans.reset();w=Math.min(640,width-12);h=Math.min(360,height-12);x=(width-w)/2;y=(height-h)/2;String[] c=ClientClans.one("CLAN");if(c!=null&&savedMotto.isEmpty()){savedMotto=c[5];badge=index(BADGES,c[6]);doctrine=index(DOCTRINES,c[7]);}rebuild();ClanPacket.send(ClanPacket.STATUS,"","",0);}
 private static int index(String[] a,String v){for(int i=0;i<a.length;i++)if(a[i].equals(v))return i;return 0;}
 private void btn(int px,int py,int pw,String label,Runnable action){addRenderableWidget(new ModernButton(px,py,pw,18,Component.literal(label),b->action.run(),0xff282a22,0xff424838));}
 private void rebuild(){if(target!=null)savedTarget=target.getValue();if(motto!=null)savedMotto=motto.getValue();clearWidgets();target=null;motto=null;int tw=(w-24)/5;String[] tabs={"Clan","Conflicto","Compañeros","Depósito","Oleadas PvE"};for(int i=0;i<5;i++){final int t=i;btn(x+12+i*tw,y+32,tw-3,tabs[i],()->{tab=t;page=0;confirm=0;rebuild();});}
  if(tab==0)btn(x+12,y+h-25,Math.max(80,(w-32)/2),"Administrar clan",()->Minecraft.getInstance().setScreen(new MainFactionScreen()));btn(x+w-88,y+h-25,76,"Cerrar",this::onClose);
  if(tab==0&&editing){motto=new EditBox(font,x+16,y+96,w-32,18,Component.literal("Lema del clan"));motto.setMaxLength(96);motto.setValue(savedMotto);addRenderableWidget(motto);btn(x+16,y+126,(w-36)/2,"Emblema: "+BADGES[badge],()->{badge=(badge+1)%BADGES.length;rebuild();});btn(x+20+(w-36)/2,y+126,(w-36)/2,DOCTRINES[doctrine],()->{doctrine=(doctrine+1)%DOCTRINES.length;rebuild();});btn(x+16,y+151,w-32,"Guardar identidad",()->ClanPacket.send(ClanPacket.PROFILE,motto.getValue(),BADGES[badge]+"|"+DOCTRINES[doctrine],0));}
  if(tab==0){if(!editing){btn(x+16,y+105,(w-36)/2,"Reclamar este chunk",()->Territory.current(false));btn(x+20+(w-36)/2,y+105,(w-36)/2,"Liberar este chunk",()->Territory.current(true));}btn(x+16,y+h-49,w-32,editing?"Volver al clan":"Personalizar clan",()->{editing=!editing;rebuild();});}
  if(tab==1){String[] war=ClientClans.one("WAR");if(war==null){target=new EditBox(font,x+16,y+77,w-32,18,Component.literal("Nombre o sigla del rival"));target.setMaxLength(32);target.setValue(savedTarget);addRenderableWidget(target);btn(x+16,y+100,(w-36)/2,siege?"Capturar territorios":"Combate sin territorios",()->{siege=!siege;confirm=0;rebuild();});btn(x+20+(w-36)/2,y+100,(w-36)/2,confirm==1?"Confirmar declaración":"Declarar conflicto",()->{if(confirm==1){ClanPacket.send(ClanPacket.DECLARE,target.getValue(),"Conflicto de supervivencia",siege?1:0);confirm=0;rebuild();}else{confirm=1;rebuild();}});}else{boolean ready=war[3].equals("0")&&war[7].equals("true")&&war[2].equals("Asedio");if(ready)btn(x+16,y+100,w-32,"Seleccionar chunk y capturar",()->{Object screen=R.make("me.danialisntcool.factionfriction.client.screen.OperationMapScreen");R.call(Minecraft.getInstance(),"setScreen",screen);});btn(x+16,y+h-49,w-32,confirm==2?"Confirmar rendición":"Rendirse",()->{if(confirm==2){ClanPacket.send(ClanPacket.SURRENDER,"","",0);confirm=0;rebuild();}else{confirm=2;rebuild();}});}}

  if(tab==2||tab==3){btn(x+w-102,y+57,42,"<",()->{page=Math.max(0,page-1);});btn(x+w-56,y+57,42,">",()->{page++;});}
  if(tab==4){String[] nexo=ClientClans.one("NEXUS"),pve=ClientClans.one("PVE");boolean active=pve!=null&&!pve[4].equals("Sin oleada activa");if(!active){if(nexo==null||!nexo[1].equals("true"))btn(x+16,y+105,w-32,"Recibir nexo (jefe)",()->ClanPacket.send(8,"","",0));else if(Integer.parseInt(nexo[4])<10)btn(x+16,y+105,w-32,"Mejorar nexo: "+(8*(Integer.parseInt(nexo[4])+1))+" hierro",()->ClanPacket.send(9,"","",0));if(nexo!=null&&nexo[2].equals("true")&&nexo[5].equals("0"))btn(x+16,y+130,w-32,pve==null||pve[3].equals("Sin oferta")?"Solicitar oferta de defensa":"Aceptar defensa "+pve[3],()->ClanPacket.send(pve==null||pve[3].equals("Sin oferta")?6:7,"","",0));}}

  if(tab==3)btn(x+16,y+h-49,w-32,"Recoger suministros y equipo (jefatura)",()->ClanPacket.send(ClanPacket.CLAIM,"","",0));
 }
 public void tick(){super.tick();ClientClans.reset();String[] war=ClientClans.one("WAR"),pve=ClientClans.one("PVE");String[] nexo=ClientClans.one("NEXUS");String layout=(war==null?"none":war[2]+war[3].equals("0")+war[7])+(pve==null?"":pve[3]+pve[4].equals("Sin oleada activa"))+(nexo==null?"":nexo[1]+nexo[2]+nexo[4]+nexo[5].equals("0"));if(!layout.equals(controls)){controls=layout;rebuild();}String[] c=ClientClans.one("CLAN");if(c!=null&&!c[1].equals(profileId)){profileId=c[1];savedMotto=c[5];badge=index(BADGES,c[6]);doctrine=index(DOCTRINES,c[7]);if(motto!=null)motto.setValue(savedMotto);rebuild();}if(++ticks%40==0)ClanPacket.send(ClanPacket.STATUS,"","",0);}
 private void text(GuiGraphics g,String s,int px,int py,int color){g.drawString(font,font.plainSubstrByWidth(s,Math.max(1,x+w-16-px)),px,py,color,false);}
 private void mateText(GuiGraphics g,String s,int yy,int color){g.drawString(font,font.plainSubstrByWidth(s,Math.max(1,w-(w>=440?150:32))),x+16,yy,color,false);}
 private void lines(GuiGraphics g,String text,int py,int color){int yy=py;for(var line:font.split(Component.literal(text),w-32)){g.drawString(font,line,x+16,yy,color);yy+=11;}}
 private void radar(GuiGraphics g){String[] self=ClientClans.one("SELF");if(w<440||self==null)return;int cx=x+w-68,cy=y+142,r=45;g.fill(cx-r,cy-r,cx+r+1,cy+r+1,0xff101410);for(int i=-r;i<=r;i+=15){g.fill(cx+i,cy-r,cx+i+1,cy+r,0xff33392b);g.fill(cx-r,cy+i,cx+r,cy+i+1,0xff33392b);}text(g,"N",cx-3,cy-r-11,0xffa5a68d);text(g,"128 m",cx-16,cy+r+5,0xffa5a68d);double px=Double.parseDouble(self[1]),pz=Double.parseDouble(self[3]);for(String[] mate:ClientClans.all("MATE")){if(!mate[5].equals(self[4]))continue;double dx=Double.parseDouble(mate[2])-px,dz=Double.parseDouble(mate[4])-pz;double scale=Math.max(128,Math.max(Math.abs(dx),Math.abs(dz)));int mx=cx+(int)Math.round(dx*r/scale),my=cy+(int)Math.round(dz*r/scale);g.fill(mx-2,my-2,mx+3,my+3,0xff9eae70);}g.fill(cx-2,cy-2,cx+3,cy+3,0xffe3debd);}
 private void emblem(GuiGraphics g,String badge){int bx=x+w-40,by=y+65,c=0xffb9b38c;if(badge.equals("MEDIC")){g.fill(bx+7,by,bx+12,by+20,c);g.fill(bx,by+7,bx+20,by+12,c);}else if(badge.equals("SKULL")){g.fill(bx+2,by,bx+18,by+13,c);g.fill(bx+5,by+13,bx+15,by+19,c);g.fill(bx+5,by+4,bx+8,by+8,0xff191b18);g.fill(bx+12,by+4,bx+15,by+8,0xff191b18);}else if(badge.equals("RADIO")){g.fill(bx,by+5,bx+20,by+20,c);g.fill(bx+4,by,bx+6,by+7,c);g.fill(bx+3,by+9,bx+12,by+17,0xff191b18);}else if(badge.equals("TOOLS")){for(int i=0;i<16;i++)g.fill(bx+i,by+15-i,bx+i+4,by+19-i,c);}else{g.fill(bx+7,by,bx+12,by+20,c);g.fill(bx,by+7,bx+20,by+12,c);for(int i=0;i<14;i++)g.fill(bx+i+2,by+i+2,bx+i+4,by+i+4,c);}}
 public void render(GuiGraphics g,int mx,int my,float partial){g.fill(0,0,width,height,0xb8000000);g.fill(x,y,x+w,y+h,0xff191b18);for(int line=y+2;line<y+h;line+=4)g.fill(x+1,line,x+w-1,line+1,0x102f3027);g.fill(x,y,x+w,y+27,0xff303128);g.fill(x,y+26,x+w,y+27,0xff969171);text(g,"CLAN DE SUPERVIVIENTES",x+12,y+10,0xffe3debd);String[] c=ClientClans.one("CLAN"),war=ClientClans.one("WAR");int white=0xffe3debd,muted=0xffa5a68d,green=0xff9eae70,red=0xffd08775;
  if(tab==0){text(g,c==null?"Sin clan: crea uno en administración":c[2]+" ["+c[3]+"] / "+c[7],x+16,y+62,white);String[] land=ClientClans.one("LAND");text(g,land==null?"Lema / identidad":"Nivel "+land[1]+" / 3 · Territorio "+land[2]+" / "+land[3]+" chunks",x+16,y+82,muted);if(c!=null){emblem(g,c[6]);if(editing){text(g,"Emblema: "+c[6]+" | "+c[5],x+16,y+180,green);}else{text(g,"Refugio protegido · compañeros · guerras · defensas PvE",x+16,y+136,green);text(g,"Último resultado: "+c[9],x+16,y+151,muted);}}}
  if(tab==1){text(g,war==null?"1. Escribe el rival · 2. Elige el modo · 3. Declara":"Conflicto activo",x+16,y+62,muted);String[] cfg=ClientClans.one("CONFIG");int yy=y+127;if(war!=null){text(g,war[1]+" / "+war[2]+" / "+war[5]+" : "+war[6],x+16,yy,white);text(g,"Preparación: "+war[3]+" s | Fin: "+war[4]+" s",x+16,yy+14,muted);text(g,war[7].equals("true")?"Defensor conectado":"Territorio protegido: defensor desconectado",x+16,yy+28,war[7].equals("true")?green:red);}else{lines(g,(siege?"Asedio: disputa chunks de frontera con un defensor conectado.":"Escaramuza: combate por puntos; no permite destruir ni capturar claims.")+" Preparación: "+(cfg==null?"5":cfg[1])+" min.",yy,muted);}
   int start=yy+48;List<String[]> list=ClientClans.all("LIST");int slots=Math.max(0,(h-236)/12);if(slots>0)text(g,"Clanes / conectados",x+16,start,muted);for(int i=0;i<Math.min(slots,list.size());i++){String[] row=list.get(i);text(g,row[1]+" ["+row[2]+"]  "+row[4]+"/"+row[3],x+16,start+14+i*12,white);}}
  if(tab==2){radar(g);text(g,"COMPAÑEROS / POSICIÓN",x+16,y+63,green);List<String[]> mates=ClientClans.all("MATE");int slots=Math.max(1,(h-126)/24);page=Math.min(page,Math.max(0,(mates.size()-1)/slots));for(int i=0;i<slots&&page*slots+i<mates.size();i++){String[] r=mates.get(page*slots+i);int yy=y+91+i*24;String pos=Math.round(Double.parseDouble(r[2]))+", "+Math.round(Double.parseDouble(r[3]))+", "+Math.round(Double.parseDouble(r[4]));mateText(g,r[1]+" / "+r[6],yy,white);mateText(g,pos+" / "+r[5],yy+11,muted);}if(mates.isEmpty())text(g,"Sin compañeros conectados",x+16,y+91,muted);}
  if(tab==3){text(g,"DEPÓSITO DEL CLAN",x+16,y+63,green);List<String[]> rewards=ClientClans.all("REWARD");int slots=Math.max(1,(h-150)/15);page=Math.min(page,Math.max(0,(rewards.size()-1)/slots));for(int i=0;i<slots&&page*slots+i<rewards.size();i++){String[] r=rewards.get(page*slots+i);text(g,r[2]+" x "+r[1],x+16,y+91+i*15,white);}if(rewards.isEmpty())lines(g,"Sin suministros pendientes. Gana puntos en combate, captura o defensa para obtener recompensas al terminar la guerra.",y+91,muted);}
  if(tab==4){String[] pve=ClientClans.one("PVE");text(g,pve==null?"Necesitas un clan":"XP: "+pve[1]+" · victorias: "+pve[2]+" · oferta: "+pve[3],x+16,y+65,green);text(g,pve==null?"":pve[4],x+16,y+82,white);String[] nexo=ClientClans.one("NEXUS");text(g,nexo==null?"":(nexo[2].equals("true")?"Nexo colocado":"Coloca el nexo en tu base")+" · "+nexo[3]+" PV · espera "+nexo[5]+" s",x+16,y+94,muted);text(g,"Acepta dentro de tu territorio. Nivel 2: 100 XP / nivel 3: 300 XP.",x+16,y+156,muted);text(g,"TOP DE CLANES / XP Y VICTORIAS PvE",x+16,y+178,green);int yy=y+193;for(String[] row:ClientClans.all("TOP")){if(yy>y+h-35)break;text(g,row[1]+". "+row[2]+" · "+row[3]+" XP · "+row[4]+" victorias",x+16,yy,white);yy+=12;}}
  super.render(g,mx,my,partial);
 }
 public boolean isPauseScreen(){return false;}
 public void renderBackground(GuiGraphics g,int mx,int my,float partial){}
}
